result.output:
"""`gh` の実行。このモジュールの関数 `run` だけが `gh` を起動する (計画の KTD11)。ほかのモジュールは `subprocess` で `gh` を
呼ばず、`run` に引数の配列を渡す。

プラグイン issue-dispatch のファイル `issue-dispatch/scripts/issue_dispatch/gh.py` をコピーし、issue-practice で使わない関数
(レート制限の再開時刻を読む関数) を除いて、トークンのログインを読む関数 `viewer_login` を足したもの。プラグインは別々に
配布するので、ファイルは共有しない。

`run` は、終了コード・標準出力・標準エラー出力の末尾・タイムアウトで打ち切ったか・失敗の種類 (`failure`) を返す。
失敗の種類は標準エラー出力と標準出力の文言から分け、再試行はしない。失敗したときの終了コード (計画の KTD10 の 4) は
呼び出し元 (CLI の入口) が決める。

テストは PATH の先頭に偽の `gh` (ファイル `issue-practice/tests/fake-gh`) のディレクトリを加えて差し替える。
"""

import json
import re
import subprocess
import time

DEFAULT_TIMEOUT = 60
STDERR_TAIL_LINES = 20
MUTATION_INTERVAL = 1.0  # 変更系の呼び出しの後に待機する秒数 (次の変更系の呼び出しと 1 秒以上空ける)

# 失敗の種類。None は成功。`missing` は gh が PATH に無いか実行権限が無い (入れる・権限を直すのが直し方)
FAILURES = ("auth", "rate_limit", "network", "timeout", "missing", "other")

_AUTH_RE = re.compile(r"HTTP 401|Bad credentials|gh auth login|not logged in", re.IGNORECASE)
_RATE_LIMIT_RE = re.compile(r"rate limit|RATE_LIMITED|secondary rate|abuse detection", re.IGNORECASE)
_NETWORK_RE = re.compile(
    r"dial tcp|connection refused|connection reset|no such host|i/o timeout|TLS handshake|proxyconnect|"
    r"network is unreachable|error connecting|could not resolve host",
    re.IGNORECASE,
)


def _graphql_error_types(stdout):
    """標準出力が GraphQL の応答なら、トップレベルの errors[].type の集合。読めなければ空。"""
    try:
        data = json.loads(stdout)
    except ValueError:
        return set()
    errors = data.get("errors") if isinstance(data, dict) else None
    if not isinstance(errors, list):
        return set()  # errors が無い・null・配列でない応答
    return {e.get("type") for e in errors if isinstance(e, dict)}


def classify(exit_code, stdout, stderr, timed_out):
    """終了コードと出力から失敗の種類を決める。成功 (終了コード 0) なら None。

    文言を見るのは `gh` 自身が書く標準エラー出力だけ。標準出力 (API の応答) には Issue の本文など利用者の書いた
    文字列が入るので、正規表現では見ず、JSON として読めたときのトップレベルの errors[].type だけを見る。
    """
    if timed_out:
        return "timeout"
    if exit_code == 0:
        return None
    if _AUTH_RE.search(stderr):
        return "auth"
    if _RATE_LIMIT_RE.search(stderr) or "RATE_LIMITED" in _graphql_error_types(stdout):
        return "rate_limit"
    if _NETWORK_RE.search(stderr):
        return "network"
    return "other"


def _tail(text, lines=STDERR_TAIL_LINES):
    return "\n".join(text.splitlines()[-lines:])


def _text(value):
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return value


def run(args, timeout=DEFAULT_TIMEOUT, mutation=False, expect_json=False, stdin=None):
    """`gh` を引数の配列で実行する。

    mutation が真なら、gh が終了した後に MUTATION_INTERVAL 秒待機してから返る。次の変更系の呼び出しがこのプロセスでも
    別のプロセス (CLI はサブコマンドごとに 1 プロセス) でも、1 秒以上空く。
    返り値: {"args", "exit_code" (タイムアウトと起動できなかったときは None), "stdout", "stderr_tail", "timed_out",
    "failure", "json" (標準出力が JSON として読めればその値、読めなければ None), "json_error" (expect_json が真で、
    標準出力が空でないのに JSON として読めなかったときの理由。それ以外は None)}

    stdin は、標準入力に渡す文字列 (`gh api graphql --input -` の本文など)。None なら標準入力は渡さない (/dev/null)。
    expect_json は、呼び出し元が標準出力に JSON を期待するときに真を渡す (`gh api` や `--json` で JSON を受け取る
    呼び出し)。引数から推測しない。`--jq` や `--template` で文字列を取り出す呼び出しや、URL や文章を出すコマンド
    (`gh issue comment` など) では渡さない。

    `gh api --paginate` は、ページごとの JSON をつないで出すので 1 つの JSON として読めない。`--slurp` と一緒に使い、
    全ページを 1 つの配列で受け取る。
    """
    args = list(args)
    try:
        completed = subprocess.run(["gh", *args], capture_output=True, text=True, timeout=timeout,
                                   input=stdin, stdin=subprocess.DEVNULL if stdin is None else None)
        exit_code, stdout, stderr, timed_out = completed.returncode, completed.stdout, completed.stderr, False
    except subprocess.TimeoutExpired as e:
        exit_code, stdout, stderr, timed_out = None, _text(e.stdout), _text(e.stderr), True
    except OSError as e:
        # 起動できなかったことを返り値で伝える。gh が PATH に無い (FileNotFoundError)・実行権限が無い (PermissionError) は
        # `missing`。それ以外 (引数が長すぎる E2BIG など、gh が入っていても起きるもの) は `other`
        failure = "missing" if isinstance(e, (FileNotFoundError, PermissionError)) else "other"
        return {"args": args, "exit_code": None, "stdout": "", "stderr_tail": f"gh を起動できない: {e}",
                "timed_out": False, "failure": failure, "json": None, "json_error": None}
    finally:
        if mutation:
            time.sleep(MUTATION_INTERVAL)
    parsed, json_error = None, None
    if stdout.strip():
        try:
            parsed = json.loads(stdout)
        except ValueError as e:
            if expect_json:
                json_error = str(e)
    return {
        "args": args,
        "exit_code": exit_code,
        "stdout": stdout,
        "stderr_tail": _tail(stderr),
        "timed_out": timed_out,
        "failure": classify(exit_code, stdout, stderr, timed_out),
        "json": parsed,
        "json_error": json_error,
    }


def failed(result):
    """`run` の結果が、呼び出し元から見て失敗か (gh が失敗した・JSON を期待したのに読めなかった)。"""
    return result["failure"] is not None or result["json_error"] is not None


def describe_failure(result):
    """失敗した `run` の結果を、CLI の出力の `gh_error` に入れる形にする。"""
    return {"args": result["args"], "exit_code": result["exit_code"], "failure": result["failure"],
            "stderr_tail": result["stderr_tail"], "json_error": result["json_error"]}


def viewer_login(timeout=DEFAULT_TIMEOUT):
    """トークンのログイン (`gh api user` の `login`) を読む。返り値は (ログイン, 失敗した `run` の結果)。

    読めたときは (ログイン, None)、読めなかったときは (None, 結果)。応答に `login` が無いときも読めなかったとして扱う。
    """
    result = run(["api", "user"], timeout=timeout, expect_json=True)
    if failed(result):
        return None, result
    data = result["json"]
    login = data.get("login") if isinstance(data, dict) else None
    if not isinstance(login, str) or not login:
        return None, {**result, "json_error": "応答に login が無い"}
    return login, None
"""識別子の解析と正規化 (計画の KTD12)。Issue の番号・`owner/repo#N`・Issue と PR とコメントの URL・マイルストーンの名前を、
このモジュールの 1 か所で解析する。ほかのモジュールとスキルは、識別子を文から解釈せず、ここの関数を使う。

解析の関数は、解釈できた値の辞書か、理由の文字列を持つ辞書 (`{"error": <理由>}`) を返す。例外は送出しない。
"""

import re

_OWNER = r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})"
_REPO = r"[A-Za-z0-9._-]+"
_NUMBER = r"[1-9][0-9]*"

_REPO_RE = re.compile(rf"^(?P<owner>{_OWNER})/(?P<repo>{_REPO})$")
_SHORT_RE = re.compile(rf"^#?(?P<number>{_NUMBER})$")
_KEY_RE = re.compile(rf"^(?P<owner>{_OWNER})/(?P<repo>{_REPO})#(?P<number>{_NUMBER})$")
_URL_RE = re.compile(
    rf"^https://github\.com/(?P<owner>{_OWNER})/(?P<repo>{_REPO})/(?P<path>issues|pull)/(?P<number>{_NUMBER})/?$")
_COMMENT_URL_RE = re.compile(
    rf"^https://github\.com/(?P<owner>{_OWNER})/(?P<repo>{_REPO})/(?P<path>issues|pull)/(?P<number>{_NUMBER})"
    r"#issuecomment-(?P<comment_id>[1-9][0-9]*)$")
_ZERO_RE = re.compile(r"(?:^|[#/])0+$")

# リリースマイルストーンの名前。`R<リリース Issue の番号> (主題)` か、リリース対象があるとき `R<番号> <リリース対象> (主題)`
# (計画の R41)。主題は最後の括弧の中で、括弧を含んでもよい
_MILESTONE_RE = re.compile(rf"^R(?P<number>{_NUMBER})(?: (?P<target>[^\s()]+))? \((?P<subject>.+)\)$")


def parse_repo(text):
    """`owner/repo` を解析する。返り値は {"owner", "repo", "repo_key"} か {"error"}。"""
    text = (text or "").strip()
    m = _REPO_RE.match(text)
    if not m or m.group("repo") in (".", ".."):
        return {"error": f"owner/repo の形ではない: {text!r}"}
    return {"owner": m.group("owner"), "repo": m.group("repo"), "repo_key": f"{m.group('owner')}/{m.group('repo')}"}


def _ref(owner, repo, number, kind, url=None):
    key = f"{owner}/{repo}#{number}" if owner else None
    return {"owner": owner, "repo": repo, "number": number, "kind": kind, "key": key,
            "url": url or (f"https://github.com/{owner}/{repo}/{'pull' if kind == 'pull' else 'issues'}/{number}"
                           if owner else None)}


def parse_ref(text, default_repo=None):
    """Issue か PR の参照を解析する。

    受け付ける形: `12`・`#12` (リポジトリは default_repo)・`owner/repo#12`・`https://github.com/owner/repo/issues/12`・
    `https://github.com/owner/repo/pull/12`。返り値は {"owner", "repo", "number", "kind", "key", "url"} か {"error"}。
    kind は URL から分かるときだけ `issue` か `pull` で、番号だけの形では None (Issue か PR かは GitHub に聞くまで分からない)。
    `12` と `#12` で default_repo が無いときは、owner・repo・key・url を None にして返す (形の検査だけをしたい呼び出し元のため)。
    """
    raw = text
    text = (text or "").strip()
    if not text:
        return {"error": "空の参照"}
    if _ZERO_RE.search(text) or re.search(r"[#/]0[0-9]", text):
        return {"error": f"番号は 1 以上で、先頭に 0 を付けない: {raw!r}"}
    m = _URL_RE.match(text)
    if m:
        if m.group("repo") in (".", ".."):
            return {"error": f"リポジトリの名前ではない: {raw!r}"}
        kind = "pull" if m.group("path") == "pull" else "issue"
        return _ref(m.group("owner"), m.group("repo"), int(m.group("number")), kind)
    m = _KEY_RE.match(text)
    if m:
        if m.group("repo") in (".", ".."):
            return {"error": f"リポジトリの名前ではない: {raw!r}"}
        return _ref(m.group("owner"), m.group("repo"), int(m.group("number")), None)
    m = _SHORT_RE.match(text)
    if m:
        number = int(m.group("number"))
        if default_repo is None:
            return _ref(None, None, number, None)
        repo = parse_repo(default_repo)
        if "error" in repo:
            return {"error": f"リポジトリの指定が {repo['error']}"}
        return _ref(repo["owner"], repo["repo"], number, None)
    if text.startswith("https://"):
        return {"error": f"Issue か PR の URL ではない: {raw!r}"}
    return {"error": f"Issue の参照として解釈できない: {raw!r}"}


def parse_comment_url(text):
    """Issue か PR のコメントの URL (`…/issues/12#issuecomment-345`) を解析する。

    返り値は {"owner", "repo", "number", "kind", "key", "url", "comment_id"} か {"error"}。
    """
    text = (text or "").strip()
    m = _COMMENT_URL_RE.match(text)
    if not m or m.group("repo") in (".", ".."):
        return {"error": f"コメントの URL ではない: {text!r}"}
    kind = "pull" if m.group("path") == "pull" else "issue"
    return {**_ref(m.group("owner"), m.group("repo"), int(m.group("number")), kind, url=text),
            "comment_id": int(m.group("comment_id"))}


def parse_milestone_name(name):
    """リリースマイルストーンの名前を解析する。返り値は {"number", "target", "subject"} か {"error"}。

    target はリリース対象の名前で、名前に無ければ None。
    """
    m = _MILESTONE_RE.match(name or "")
    if not m:
        return {"error": f"リリースマイルストーンの名前 (R<番号> (主題) か R<番号> <リリース対象> (主題)) ではない: {name!r}"}
    subject = m.group("subject").strip()
    if not subject:
        return {"error": f"主題が空: {name!r}"}
    return {"number": int(m.group("number")), "target": m.group("target"), "subject": subject}


def same_issue(a, b):
    """2 つの参照 (parse_ref の結果) が同じ Issue か。owner と repo の大文字と小文字は区別しない (GitHub が区別しないため)。"""
    if not a.get("key") or not b.get("key"):
        return False
    return a["key"].lower() == b["key"].lower()
"""テストで偽の `gh` (ファイル `issue-practice/tests/fake-gh`) を使うための基底クラス。

PATH の先頭に偽の `gh` のディレクトリを加え、環境変数で振る舞いを決める。実物の `gh` は使わない。
プラグイン issue-dispatch のファイル `issue-dispatch/tests/test_project.py` のクラス `FakeGhCase` と同じ形。
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
SCRIPTS = os.path.join(HERE, "..", "scripts")
ENTRY = os.path.join(SCRIPTS, "issue_practice.py")
FAKE = os.path.join(HERE, "fake-gh")
FIXTURES = os.path.join(HERE, "fixtures", "gh")

if SCRIPTS not in sys.path:
    sys.path.insert(0, SCRIPTS)

_ENV_KEYS = ("PATH", "FAKE_GH_ARGS", "FAKE_GH_RESPONSES", "FAKE_GH_MODE", "FAKE_GH_SLEEP", "FAKE_GH_EXIT")


def fixture(name, kind="stdout"):
    with open(os.path.join(FIXTURES, f"{name}.{kind}"), encoding="utf-8") as f:
        return f.read()


def fixture_json(name):
    return json.loads(fixture(name))


class FakeGhCase(unittest.TestCase):

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.root = self._tmp.name
        self.bin = os.path.join(self.root, "bin")
        os.makedirs(self.bin)
        os.symlink(FAKE, os.path.join(self.bin, "gh"))
        self.args_file = os.path.join(self.root, "args.jsonl")
        self.responses_file = os.path.join(self.root, "responses.json")
        self._saved = {k: os.environ.get(k) for k in _ENV_KEYS}
        os.environ["PATH"] = self.bin + os.pathsep + os.environ.get("PATH", "")
        os.environ["FAKE_GH_ARGS"] = self.args_file
        os.environ["FAKE_GH_RESPONSES"] = self.responses_file
        for k in ("FAKE_GH_MODE", "FAKE_GH_SLEEP", "FAKE_GH_EXIT"):
            os.environ.pop(k, None)
        self.responses([])

    def tearDown(self):
        for k, v in self._saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        self._tmp.cleanup()

    def responses(self, entries):
        with open(self.responses_file, "w", encoding="utf-8") as f:
            json.dump(entries, f, ensure_ascii=False)

    def recorded_full(self):
        if not os.path.exists(self.args_file):
            return []
        with open(self.args_file, encoding="utf-8") as f:
            return [json.loads(line) for line in f if line.strip()]

    def recorded(self):
        return [r["args"] for r in self.recorded_full()]

    def cli(self, *args, stdin=None):
        """CLI の入口をサブプロセスで実行する。返り値は (終了コード, 標準出力を JSON として読んだ値か None, 標準エラー出力)。"""
        completed = subprocess.run([sys.executable, ENTRY, *args], capture_output=True, text=True, input=stdin,
                                   env=dict(os.environ))
        try:
            payload = json.loads(completed.stdout) if completed.stdout.strip() else None
        except ValueError:
            payload = None
        return completed.returncode, payload, completed.stderr
#!/usr/bin/env python3
"""テストで、PATH の先頭に gh の名前で置く偽のコマンド。

実際の gh の代わりに、環境変数の指示どおりに振る舞う。プラグイン issue-dispatch のファイル issue-dispatch/tests/fake-gh をコピーしたもの
(計画 docs/plans/2026-11-13-2156-feat-issue-practice-plugin-plan.md の KTD11。プラグインは別々に配布するので、ファイルは共有しない)。

- FAKE_GH_ARGS: 受けた引数 (argv[1:]) と標準入力の中身 (stdin) と時刻と cwd を JSON の 1 行として追記するファイル
- FAKE_GH_SLEEP: 応答の前に待機する秒数 (デフォルトは 0)
- FAKE_GH_FIXTURES: 固定データのディレクトリ (デフォルトはこのファイルと同じディレクトリの fixtures/gh)
- FAKE_GH_MODE:
    ok              FAKE_GH_RESPONSES の応答の指定に従う (デフォルト)
    auth_expired    固定データ auth-invalid-token を返す (終了コード 1)
    not_logged_in   固定データ auth-not-logged-in を返す (終了コード 4)
    rate_limited    固定データ graphql-rate-limited を返す (終了コード 1)
    network         固定データ network-unreachable を返す (終了コード 1)
    hang            応答せずに終了しない (呼び出し元のタイムアウトを試す)
    exit            何も書かずに FAKE_GH_EXIT (デフォルトは 1) で終了する
- FAKE_GH_RESPONSES: 応答の指定の JSON ファイル。要素の配列で、受けた引数に最初に一致した要素を返す。要素のキー:
    prefix    引数の先頭がこの配列と同じなら一致 (例: ["issue", "view"])
    contains  この配列の要素をすべて含めば一致 (prefix と両方書けば両方)
    substring この文字列を含む引数が 1 つでもあるか、標準入力の中身に含まれれば一致 (GraphQL の操作名などで
              識別する。`gh api graphql --input -` の本文は標準入力に来る)。文字列の配列なら、すべてが一致すること。ほかの条件と両方書けば両方
    stdout    標準出力に書く文字列。オブジェクトや配列なら JSON にして書く。{"fixture": "<場合>"} なら固定データの <場合>.stdout の中身
    stderr    標準エラー出力に書く文字列 (デフォルトは空)
    exit      終了コード (デフォルトは 0)
    once      真なら 1 回だけ使い、使ったら used を真にしてファイルに書き戻す (書き込みの直後に別の値を返す場合を表す)
  一致する要素が無ければ、標準エラー出力に引数を書いて終了コード 99 で終了する (指定の漏れを、成功した応答と取り違えないため)
"""

import json
import os
import sys
import time

HERE = os.path.dirname(os.path.realpath(__file__))  # シンボリックリンクで gh の名前に置かれるので、実体の場所


def fixture(name, kind):
    base = os.environ.get("FAKE_GH_FIXTURES") or os.path.join(HERE, "fixtures", "gh")
    try:
        with open(os.path.join(base, f"{name}.{kind}"), encoding="utf-8") as f:
            return f.read()
    except OSError:
        return ""


def record(args, stdin_text):
    path = os.environ.get("FAKE_GH_ARGS")
    if path:
        with open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps({"args": args, "stdin": stdin_text, "time": time.time(), "cwd": os.getcwd()}, ensure_ascii=False) + "\n")


def respond(stdout, stderr, exit_code):
    sys.stdout.write(stdout)
    sys.stdout.flush()
    sys.stderr.write(stderr)
    sys.stderr.flush()
    sys.exit(exit_code)


def matches(entry, args, stdin_text):
    prefix = entry.get("prefix")
    contains = entry.get("contains")
    substring = entry.get("substring")
    if prefix is not None and args[:len(prefix)] != list(prefix):
        return False
    if contains is not None and not all(c in args for c in contains):
        return False
    if substring is not None:
        needles = [substring] if isinstance(substring, str) else list(substring)
        if not all(any(s in a for a in args) or s in stdin_text for s in needles):
            return False
    return prefix is not None or contains is not None or substring is not None


def main():
    args = sys.argv[1:]
    stdin_text = "" if sys.stdin.isatty() else sys.stdin.read()
    record(args, stdin_text)
    sleep = float(os.environ.get("FAKE_GH_SLEEP", "0") or 0)
    if sleep:
        time.sleep(sleep)
    mode = os.environ.get("FAKE_GH_MODE", "ok")
    if mode == "hang":
        while True:
            time.sleep(1)
    if mode == "auth_expired":
        respond(fixture("auth-invalid-token", "stdout"), fixture("auth-invalid-token", "stderr"), 1)
    if mode == "not_logged_in":
        respond(fixture("auth-not-logged-in", "stdout"), fixture("auth-not-logged-in", "stderr"), 4)
    if mode == "rate_limited":
        respond(fixture("graphql-rate-limited", "stdout"), fixture("graphql-rate-limited", "stderr"), 1)
    if mode == "network":
        respond(fixture("network-unreachable", "stdout"), fixture("network-unreachable", "stderr"), 1)
    if mode == "exit":
        respond("", "", int(os.environ.get("FAKE_GH_EXIT", "1")))
    if mode != "ok":
        respond("", f"fake-gh: 知らないモード {mode!r}\n", 98)
    path = os.environ.get("FAKE_GH_RESPONSES")
    entries = []
    if path:
        with open(path, encoding="utf-8") as f:
            text = f.read()
        entries = json.loads(text) if text.strip() else []
    for entry in entries:
        if entry.get("used") or not matches(entry, args, stdin_text):
            continue
        if entry.get("once"):
            entry["used"] = True
            with open(path, "w", encoding="utf-8") as f:
                json.dump(entries, f, ensure_ascii=False)
        stdout = entry.get("stdout", "")
        if isinstance(stdout, dict) and "fixture" in stdout:
            stdout = fixture(stdout["fixture"], "stdout")
        elif not isinstance(stdout, str):
            stdout = json.dumps(stdout, ensure_ascii=False)
        respond(stdout, entry.get("stderr", ""), int(entry.get("exit", 0)))
    respond("", f"fake-gh: 応答の指定に一致しない引数 {args!r}\n", 99)


if __name__ == "__main__":
    main()

"""記録のコメントの 1 行目の生成と解析、Issue のコメントの一覧から記録を集めること (計画の KTD4・KTD5)。

形の SSOT は、文書 `issue-practice/references/record-comments.md` とこのモジュールの定数 KINDS・KEYS。
テスト (ファイル `issue-practice/tests/test_docs.py`) が、文書の表と定数が一致することを確認する。

関数は、解析できた値の辞書か、理由の配列を持つ辞書 (`{"errors": [...]}`) を返す。例外は送出しない。
"""

import datetime
import re

from issue_practice import draft, gh, refs

PREFIX = "issue-practice:"

# 種類ごとの必須のキーと任意のキー。where は書く場所 (comment: 記録のコメントの 1 行目、body: 作る Issue の本文の末尾の行)。
# 順序は文書の表の順で、records format はこの順にキーを並べる
KINDS = {
    "session": {"required": ("role", "session"), "optional": ("branch", "previous"), "where": "comment"},
    "approval": {"required": ("draft",), "optional": (), "where": "comment"},
    "plan-change": {"required": (), "optional": ("draft",), "where": "comment"},
    "report": {"required": ("type",), "optional": ("pr",), "where": "comment"},
    "draft-removed": {"required": ("date",), "optional": ("draft",), "where": "comment"},
    "current-swap": {"required": ("date",), "optional": ("old",), "where": "comment"},
    "release-start": {"required": (), "optional": (), "where": "comment"},
    "dependency-resolved": {"required": ("issue",), "optional": (), "where": "comment"},
    "close-check": {"required": ("result",), "optional": (), "where": "comment"},
    "abandon": {"required": ("session",), "optional": (), "where": "comment"},
    "created-from": {"required": ("draft", "key"), "optional": (), "where": "body"},
}

ROLES = ("managing", "working", "self-managing")
REPORT_TYPES = ("pr", "check", "split", "condition-change", "carve-out", "suspend")
RESULTS = ("pass", "fail")

_SESSION_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]*$")
_BRANCH_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/-]*$")
_KEY_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
_KIND_RE = re.compile(r"^[a-z][a-z-]*$")
_PAIR_RE = re.compile(r"^(?P<key>[a-z][a-z-]*)=(?P<value>.*)$")


def _enum(values):
    def check(value):
        return None if value in values else f"{' / '.join(values)} のどれか"
    return check


def _pattern(regex, description):
    def check(value):
        return None if regex.match(value) else description
    return check


def _branch(value):
    if not _BRANCH_RE.match(value) or ".." in value:
        return "英数字で始まり、英数字・.・_・/・- が続くブランチの名前 (.. を含まない)"
    return None


def _draft(value):
    parsed = draft.parse_file_name(value)
    return parsed["error"] if "error" in parsed else None


def _date(value):
    try:
        datetime.date.fromisoformat(value)
    except ValueError:
        return "YYYY-MM-DD の日付"
    return None if re.match(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$", value) else "YYYY-MM-DD の日付"


def _issue(value):
    parsed = refs.parse_ref(value)
    if "error" in parsed or value.startswith("https://") or value.isdigit():
        return "#番号 か owner/repo#番号 の Issue の参照"
    return None


def _pr_url(value):
    parsed = refs.parse_ref(value)
    if "error" in parsed or parsed["kind"] != "pull":
        return "PR の URL (https://github.com/<owner>/<repo>/pull/<番号>)"
    return None


# キーごとの値の検査。値が形どおりなら None、違えば期待する形の説明を返す
KEYS = {
    "role": _enum(ROLES),
    "session": _pattern(_SESSION_RE, "英数字で始まり、英数字・_・.・- が続くセッションの ID"),
    "previous": _pattern(_SESSION_RE, "英数字で始まり、英数字・_・.・- が続くセッションの ID"),
    "branch": _branch,
    "draft": _draft,
    "type": _enum(REPORT_TYPES),
    "pr": _pr_url,
    "date": _date,
    "old": _issue,
    "issue": _issue,
    "result": _enum(RESULTS),
    "key": _pattern(_KEY_RE, "英数字で始まり、英数字・.・_・- が続くキー"),
}


def _check(kind, values, where):
    """種類と値を検査し、誤りの配列を返す。"""
    errors = []
    spec = KINDS.get(kind)
    if spec is None:
        return [f"知らない種類: {kind!r}"]
    if where is not None and spec["where"] != where:
        place = "Issue の本文の末尾の行" if spec["where"] == "body" else "記録のコメントの 1 行目"
        errors.append(f"種類 {kind} は{place}だけで使う")
    allowed = spec["required"] + spec["optional"]
    for key in values:
        if key not in allowed:
            errors.append(f"種類 {kind} に知らないキー: {key!r} (書けるキー: {', '.join(allowed) or 'なし'})")
    for key in spec["required"]:
        if key not in values:
            errors.append(f"種類 {kind} の必須のキーが無い: {key}")
    for key, value in values.items():
        if key not in allowed:
            continue
        if not value or any(c.isspace() for c in value):
            errors.append(f"キー {key} の値が空か、空白を含む")
            continue
        problem = KEYS[key](value)
        if problem:
            errors.append(f"キー {key} の値 {value!r} が {problem} ではない")
    return errors


def format_line(kind, values, where=None):
    """1 行目を作る。values はキーと値の辞書。返り値は {"line"} か {"errors"}。キーは KINDS の順に並べる。"""
    errors = _check(kind, values, where)
    if errors:
        return {"errors": errors}
    spec = KINDS[kind]
    parts = [PREFIX, kind] + [f"{key}={values[key]}" for key in spec["required"] + spec["optional"] if key in values]
    return {"line": " ".join(parts)}


def is_record_line(line):
    return (line or "").startswith(PREFIX)


def parse_line(line, where=None):
    """1 行目を解析する。返り値は {"kind", "values"} か {"errors"}。where を渡すと、その場所で使える種類かも検査する。"""
    line = (line or "").rstrip("\r")
    if not is_record_line(line):
        return {"errors": [f"{PREFIX} で始まらない"]}
    tokens = line[len(PREFIX):].split()
    if not tokens:
        return {"errors": ["種類が無い"]}
    kind, errors, values = tokens[0], [], {}
    if not _KIND_RE.match(kind):
        return {"errors": [f"種類の形ではない: {kind!r}"]}
    for token in tokens[1:]:
        m = _PAIR_RE.match(token)
        if not m:
            errors.append(f"<キー>=<値> の形ではない: {token!r}")
            continue
        if m.group("key") in values:
            errors.append(f"同じキーが 2 回ある: {m.group('key')}")
            continue
        values[m.group("key")] = m.group("value")
    errors += _check(kind, values, where)
    if errors:
        return {"errors": errors}
    return {"kind": kind, "values": values}


def parse_assignments(items):
    """`<キー>=<値>` の文字列の配列を辞書にする。返り値は ({キー: 値}, 誤りの配列)。"""
    values, errors = {}, []
    for item in items:
        m = _PAIR_RE.match(item)
        if not m:
            errors.append(f"<キー>=<値> の形ではない: {item!r}")
        elif m.group("key") in values:
            errors.append(f"同じキーが 2 回ある: {m.group('key')}")
        else:
            values[m.group("key")] = m.group("value")
    return values, errors


def _split_body(body):
    first, _, rest = (body or "").partition("\n")
    return first.rstrip("\r"), rest.lstrip("\r\n")


def collect(comments, login):
    """コメントの配列 (REST の issue comment の形) から記録を集める。

    投稿者 (user.login) が login と違うコメントと、1 行目が PREFIX で始まらないコメントは除く。ログインは大文字と小文字を
    区別しない。返り値は {"records", "invalid", "skipped_other_authors"}。records の要素は
    {"kind", "values", "id", "url", "created_at", "updated_at", "body"} (body は 1 行目と続く空行を除いた本文)、
    invalid の要素は {"id", "url", "line", "errors"}。
    """
    records, invalid, skipped = [], [], 0
    for comment in comments:
        author = ((comment.get("user") or {}).get("login") or "")
        if author.lower() != (login or "").lower():
            if is_record_line(_split_body(comment.get("body"))[0]):
                skipped += 1
            continue
        first, rest = _split_body(comment.get("body"))
        if not is_record_line(first):
            continue
        parsed = parse_line(first, where="comment")
        base = {"id": comment.get("id"), "url": comment.get("html_url")}
        if "errors" in parsed:
            invalid.append({**base, "line": first, "errors": parsed["errors"]})
            continue
        records.append({"kind": parsed["kind"], "values": parsed["values"], **base,
                        "created_at": comment.get("created_at"), "updated_at": comment.get("updated_at"), "body": rest})
    return {"records": records, "invalid": invalid, "skipped_other_authors": skipped}


def fetch_comments(ref):
    """Issue (か PR) のコメントを、投稿の順に全部読む。返り値は (コメントの配列, None) か (None, 失敗した gh の結果)。"""
    result = gh.run(["api", f"repos/{ref['owner']}/{ref['repo']}/issues/{ref['number']}/comments", "--paginate", "--slurp"],
                    expect_json=True)
    if gh.failed(result):
        return None, result
    pages = result["json"]
    if not isinstance(pages, list) or not all(isinstance(p, list) for p in pages):
        return None, {**result, "json_error": "応答がページの配列 (--slurp の形) ではない"}
    return [c for page in pages for c in page if isinstance(c, dict)], None


def list_records(ref):
    """Issue の記録を集める。返り値は ({"login", "records", "invalid", "skipped_other_authors"}, None) か
    (None, 失敗した gh の結果)。"""
    login, failure = gh.viewer_login()
    if failure:
        return None, failure
    comments, failure = fetch_comments(ref)
    if failure:
        return None, failure
    return {"login": login, **collect(comments, login)}, None
"""計画案のファイルの共通の部分。保存先の確認・ファイル名・先頭の書式の解析・本文の照合 (計画の KTD7・KTD13・KTD14)。

書式の SSOT は、文書 `issue-practice/references/draft-plan.md` とこのモジュール。計画案の中身 (スキルごとの節) は扱わない。
関数は、解析できた値の辞書か、理由を持つ辞書を返す。例外は送出しない (ファイルを開けないときの OSError を除く)。
"""

import os
import re
import subprocess

from issue_practice import bodies, refs

DRAFT_DIR = "tmp/issue-practice"

# プラグイン issue-practice のスキルの名前 (計画の KD3)。ファイル名の <スキル名> はこのどれか
SKILLS = (
    "new-issue",
    "managing-issue-plan",
    "managing-issue-run",
    "managing-issue-close",
    "working-issue",
    "release-plan",
    "release-issue-plan",
    "release-run",
    "release-close",
)

TARGET_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")
FILENAME_RE = re.compile(r"^(?P<date>[0-9]{8})-(?P<time>[0-9]{4})-(?P<rest>[a-z0-9][a-z0-9-]*)\.md$")
TITLE_RE = re.compile(r"^# 計画案: (?P<title>\S.*)$")
SOURCES_HEADING = "元にした Issue"
SOURCE_RE = re.compile(r"^- (?P<url>\S+) 本文の SHA-256: (?P<sha256>[0-9a-f]{64})$")
NONE_ITEM = "- なし"

# git を実行するときに消す環境変数。--root で渡したリポジトリだけを基準にするため (hook の中などで GIT_DIR が設定されていても)
_GIT_ENV_KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_COMMON_DIR", "GIT_PREFIX")


def parse_file_name(name):
    """ファイル名を解析する。返り値は {"date", "time", "skill", "target"} か {"error"}。"""
    m = FILENAME_RE.match(name or "")
    if not m:
        return {"error": f"ファイル名が <YYYYMMDD>-<hhmm>-<スキル名>-<対象>.md の形ではない: {name!r}"}
    rest = m.group("rest")
    for skill in sorted(SKILLS, key=len, reverse=True):
        if rest.startswith(skill + "-") and TARGET_RE.match(rest[len(skill) + 1:]):
            return {"date": m.group("date"), "time": m.group("time"), "skill": skill, "target": rest[len(skill) + 1:]}
    return {"error": f"ファイル名の <スキル名>-<対象> が、スキルの名前と対象の組になっていない: {name!r}"}


def file_name(skill, target, stamp):
    """ファイル名を作る。stamp は `YYYYMMDD-hhmm`。返り値は {"file_name"} か {"error"}。"""
    if skill not in SKILLS:
        return {"error": f"知らないスキルの名前: {skill!r}"}
    if not TARGET_RE.match(target or ""):
        return {"error": f"対象は英小文字・数字・ハイフンで書く: {target!r}"}
    name = f"{stamp}-{skill}-{target}.md"
    parsed = parse_file_name(name)
    if "error" in parsed:
        return parsed
    return {"file_name": name}


def _git(root, *args):
    env = {k: v for k, v in os.environ.items() if k not in _GIT_ENV_KEYS}
    try:
        completed = subprocess.run(["git", "-C", root, *args], capture_output=True, text=True, env=env,
                                   stdin=subprocess.DEVNULL)
    except OSError as e:
        return {"args": ["git", "-C", root, *args], "exit_code": None, "stdout": "", "stderr": f"git を起動できない: {e}"}
    return {"args": ["git", "-C", root, *args], "exit_code": completed.returncode, "stdout": completed.stdout,
            "stderr": completed.stderr}


def check_dir(root):
    """計画案のディレクトリ (root の tmp/issue-practice/) が git に無視されているかを確認する。

    root は、リポジトリのルートの絶対パス。返り値は次のどれか。
      {"status": "ok", "dir": <絶対パス>}
      {"status": "unsatisfied", "errors": [<理由>]}   root がルートでない・無視されていない
      {"status": "git_failed", "git_error": {...}}     git が失敗した (リポジトリでないなど)
    """
    if not root or not os.path.isabs(root):
        return {"status": "unsatisfied", "errors": [f"--root はリポジトリのルートの絶対パスで渡す: {root!r}"]}
    top = _git(root, "rev-parse", "--show-toplevel")
    if top["exit_code"] != 0:
        return {"status": "git_failed", "git_error": top}
    if os.path.realpath(top["stdout"].strip()) != os.path.realpath(root):
        return {"status": "unsatisfied",
                "errors": [f"--root がリポジトリのルートではない (ルートは {top['stdout'].strip()})"]}
    ignored = _git(root, "check-ignore", "-q", "--", DRAFT_DIR + "/")
    if ignored["exit_code"] == 1:
        return {"status": "unsatisfied",
                "errors": [f"ディレクトリ {DRAFT_DIR}/ が git に無視されていない。.gitignore に tmp/ を足してコミットしてから、"
                           "もう一度実行する (スキルは .gitignore を変えない)"]}
    if ignored["exit_code"] != 0:
        return {"status": "git_failed", "git_error": ignored}
    return {"status": "ok", "dir": os.path.join(root, DRAFT_DIR)}


def new_path(root, skill, target, stamp):
    """新しい計画案のパスを決め、ディレクトリを作る。既にあるファイルの名前は返さない。

    返り値は check_dir と同じ形で、ok のときは {"status": "ok", "path", "relative", "file_name"}。
    """
    name = file_name(skill, target, stamp)
    if "error" in name:
        return {"status": "unsatisfied", "errors": [name["error"]]}
    checked = check_dir(root)
    if checked["status"] != "ok":
        return checked
    path = os.path.join(checked["dir"], name["file_name"])
    if os.path.lexists(path):
        return {"status": "unsatisfied",
                "errors": [f"計画案のファイルが既にある (上書きしない): {path}。時刻か対象を変えて作り直す"]}
    os.makedirs(checked["dir"], exist_ok=True)
    return {"status": "ok", "path": path, "relative": f"{DRAFT_DIR}/{name['file_name']}", "file_name": name["file_name"]}


def parse(text, name):
    """計画案の先頭の書式を解析する。name はファイル名 (ディレクトリを含まない)。

    返り値は {"file_name", "title", "skill", "target", "created", "sources", "sections", "errors"}。errors は
    {"line" (1 から数える行番号。行に結び付かない誤りは null), "message"} の配列で、空なら形どおり。
    sources は {"issue" (owner/repo#番号), "url", "sha256", "line"} の配列、sections は節「元にした Issue」の後の
    レベル 2 の節 {"title", "line"} の配列。
    """
    errors = []
    result = {"file_name": name, "title": None, "skill": None, "target": None, "created": None, "sources": [],
              "sections": [], "errors": errors}
    parsed_name = parse_file_name(name)
    if "error" in parsed_name:
        errors.append({"line": None, "message": parsed_name["error"]})
    else:
        result.update(skill=parsed_name["skill"], target=parsed_name["target"],
                      created=f"{parsed_name['date'][:4]}-{parsed_name['date'][4:6]}-{parsed_name['date'][6:]} "
                              f"{parsed_name['time'][:2]}:{parsed_name['time'][2:]}")
    lines = bodies.split_lines(text)
    visible = bodies.outside_fences(lines)
    m = TITLE_RE.match(lines[0].rstrip("\r")) if lines else None
    if not m:
        errors.append({"line": 1, "message": "1 行目が「# 計画案: <題>」ではない"})
    else:
        result["title"] = m.group("title").strip()
    level2 = [(i, bodies.heading(lines[i])[1]) for i in sorted(visible)
              if bodies.heading(lines[i]) and bodies.heading(lines[i])[0] == 2]
    source_headings = [i for i, title in level2 if title == SOURCES_HEADING]
    if not source_headings:
        errors.append({"line": None, "message": f"節「{SOURCES_HEADING}」(## {SOURCES_HEADING}) が無い"})
        return result
    if len(source_headings) > 1:
        errors.append({"line": source_headings[1] + 1, "message": f"節「{SOURCES_HEADING}」が複数ある"})
    start = source_headings[0]
    if level2[0][0] != start:
        errors.append({"line": start + 1, "message": f"節「{SOURCES_HEADING}」が最初のレベル 2 の見出しではない"})
    following = [i for i, _ in level2 if i > start]
    end = following[0] if following else len(lines)
    result["sections"] = [{"title": title, "line": i + 1} for i, title in level2 if i > start]
    items, has_none, seen = [], False, {}
    for i in range(start + 1, end):
        line = lines[i].rstrip("\r")
        if not line.strip():
            continue
        if line == NONE_ITEM:
            has_none = True
            items.append(i)
            continue
        sm = SOURCE_RE.match(line)
        if not sm:
            errors.append({"line": i + 1, "message": "「- <Issue の URL> 本文の SHA-256: <64 桁の 16 進数>」か「- なし」ではない"})
            continue
        ref = refs.parse_ref(sm.group("url"))
        if "error" in ref or not sm.group("url").startswith("https://"):
            errors.append({"line": i + 1, "message": f"Issue か PR の URL ではない: {sm.group('url')}"})
            continue
        key = ref["key"].lower()
        if key in seen:
            errors.append({"line": i + 1, "message": f"同じ Issue が 2 回ある (行 {seen[key]})"})
            continue
        seen[key] = i + 1
        items.append(i)
        result["sources"].append({"issue": ref["key"], "url": ref["url"], "sha256": sm.group("sha256"), "line": i + 1})
    if not items:
        errors.append({"line": start + 1, "message": f"節「{SOURCES_HEADING}」に項目が無い (無ければ「- なし」と書く)"})
    elif has_none and result["sources"]:
        errors.append({"line": start + 1, "message": "「- なし」と Issue の項目が両方ある"})
    return result


def read(path):
    """計画案のファイルを読んで parse する。ファイルを開けなければ OSError を送出する。"""
    with open(path, encoding="utf-8") as f:
        text = f.read()
    return parse(text, os.path.basename(path))


def compare(sources):
    """節「元にした Issue」の Issue の本文を再度読み込み、ハッシュ値を比べる。

    返り値は {"results": [{"issue", "url", "sha256_draft", "sha256_now", "changed", "updated_at"}], "gh_error"}。
    gh が失敗したら、そこで止めて gh_error に失敗した gh の結果を入れる (残りは読まない)。
    """
    results = []
    for source in sources:
        ref = refs.parse_ref(source["url"])
        issue, failure = bodies.fetch_issue(ref)
        if failure:
            return {"results": results, "gh_error": failure}
        results.append({"issue": source["issue"], "url": source["url"], "sha256_draft": source["sha256"],
                        "sha256_now": issue["sha256"], "changed": issue["sha256"] != source["sha256"],
                        "updated_at": issue["updated_at"]})
    return {"results": results, "gh_error": None}
